window.kbPageData["views/entry/k-be3dd7a10e3b2753"] = {"key":"entry/k-be3dd7a10e3b2753","state":{"route":"entry/k-be3dd7a10e3b2753"},"node":{"id":"k-be3dd7a10e3b2753","mode":"k","title":"不适用诉讼时效的请求权","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["停止侵害、排除妨碍、消除危险及特定物权返还请求不适用诉讼时效"],"qs":["国考 2024 行政执法 行测#13"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"《民法典》第一百九十六条规定，停止侵害、排除妨碍、消除危险的请求，不动产物权人或登记的动产物权人返还财产的请求，以及支付抚养费、赡养费或者扶养费的请求，均不适用诉讼时效。其他依法不适用诉讼时效的请求权也属例外。","review":{"definition":"《民法典》第一百九十六条规定，停止侵害、排除妨碍、消除危险的请求，不动产物权人或登记的动产物权人返还财产的请求，以及支付抚养费、赡养费或者扶养费的请求，均不适用诉讼时效。其他依法不适用诉讼时效的请求权也属例外。","explanation":"①拆除挡路围墙属于排除妨碍，②修复可能导致儿童坠落的下水道属于消除危险。解析将③表述为停止侵害，按题意，房屋权利人要求占用人搬离也可直接归入不动产物权人请求返还财产。④要求支付专利使用费是金钱给付请求，题中没有适用例外的条件，因此选①②③，即C。","references":[],"evidence":"不动产物权和登记的动产物权的权利人请求返还财产","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#13":{"paper":"国考 2024 行政执法 行测","n":13,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",3],"asrc":["6493f3a6a55c38431852.pdf",5],"card":"373d3c8b70e80f36d9d3207c","links":[{"id":"k-be3dd7a10e3b2753","role":"直接考查","why":"这些法定例外用于判断拆除妨碍通行的围墙、消除坠落危险及要求房屋占用人搬离的请求。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-be3dd7a10e3b2753":[["国考 2024 行政执法 行测#13"]]}};
